    S.push({ p: tube([[...F(0.02, 0.55), nw], [...F(0.0, 1.4), nw * 1.02], [...F(-0.08, 2.3), nw * 1.15]], { flat1: true }), c: o.lizard ? o.skin : skin, m: 'skin', sub: neckSub, tex: o.lizard ? 'scale' : undefined, texSize: 0.5 });
    S.push(...bust(o, fem, cr));

    /* --- 4. капюшон вокруг лица (за лицом, поверх плеч) --- */
    const hooded = o.gear === 'hood' || o.gear === 'coif' || o.gear === 'antlerHood' || o.gear === 'hideHood' || o.gear === 'lizardHood';
    if (hooded) S.push(...hoodBack(F, R, o, g));
    if (o.gear === 'hoodDown') S.push({ p: [F(-1.9, 2.4), F(-1.6, 1.6), F(-0.9, 1.25), F(-0.2, 1.5), F(0.5, 1.6), F(1.2, 1.5), F(1.8, 2.0), F(1.5, 2.6), F(0.4, 2.35), F(-0.8, 2.6)], c: g.c, m: 'cloth', belly: 0.4,
      lines: [{ p: [F(-1.4, 1.9), F(-0.4, 1.9), F(0.9, 1.95)], w: 2, a: 0.5 }, { p: [F(-1.2, 2.2), F(0.2, 2.1)], w: 1.5, a: 0.4 }] });

    /* --- 5. лицо --- */
    if (o.lizard) S.push(...lizardHead(F, R, o));
    else S.push(...face(F, R, o, { fem, age, cr, skin, dark, hair, browC, x }));

    /* --- 6. волосы спереди --- */
