    S.push({ p: ear, c: skin, m: 'skin', line: 0.8, lc: tone(skin, -0.75), id: 'ear',
      lines: [{ p: [F(-0.44, -0.08), F(-0.58, -0.06), F(-0.6, 0.12), F(-0.52, 0.28)], w: 1.6, c: A(tone(skin, -0.6), 0.7) }] });

