    S.push(stroke([N(0.54 - 0.05 * nb, 0.3), N(0.56 - 0.05 * nb, 0.42), N(0.68, 0.45)], 2.2, tone(skin, -0.7), 0.8));
    S.push(stroke([N(0.78, 0.44), N(0.88, 0.44), N(0.97, 0.38)], 2, tone(skin, -0.7), 0.6));
