    S.push({ p: [F(0.35, my + 0.01), F(0.6, my + 0.015), F(0.82, my - 0.01), F(0.72, my + 0.07 * thin), F(0.52, my + 0.08 * thin)], c: lip, m: 'skin', line: 0, rim: 0, ao: 0.4, glint: fem ? [[...F(0.56, my + 0.045), R * 0.05]] : [] });
